      '//! Named primitive Boolean equality and negation operations.\n//!\n//! # When to use\n//! Prefer `==`, `!=`, and `!` in ordinary expressions. Import [`equals`], [`notEquals`], or [`not`]\n//! when an operation must be passed or selected by name.\n//!\n//! # Details\n//! These functions return the same Boolean results as the operators. They allocate no storage and\n//! add no Effect channels.\n//!\n//! # Examples\n//! ## Compose named Boolean operations\n//! ```silk\n//! import silk.bool\n//!\n//! pub fn main() -> i32 {\n//!   let accepted = bool.equals(true, bool.not(false))\n//!   if bool.notEquals(accepted, true) {\n//!     return 1\n//!   }\n//!   return 42\n//! }\n//! ```\n\n/// Returns `true` when `left` and `right` have the same Boolean value.\npub fn equals(left: bool, right: bool) -> bool {\n  return Intrinsic.boolEquals(left, right)\n}\n\n/// Returns `true` when `left` and `right` have different Boolean values.\npub fn notEquals(left: bool, right: bool) -> bool {\n  return Intrinsic.boolNotEquals(left, right)\n}\n\n/// Returns the logical negation of `value`.\npub fn not(value: bool) -> bool {\n  return Intrinsic.boolNot(value)\n}\n',
