    source:
      "//! Deterministic seeded hashing contracts for hash maps, hash sets, and user-defined key types.\n//!\n//! # When to use\n//! Implement [`HashKey`] when a type will be stored as a hashed key. Use [`mix`] for the first\n//! integer field and [`combine`] for further fields, feeding every field that participates in\n//! equality. [`Word`] is the ready-made key for one `u64`.\n//!\n//! # Details\n//! A [`HashSeed`] belongs to a collection, not to each key. The same seed, keys, and operations\n//! produce the same bucket presentation order on every supported target, independent of addresses or ambient\n//! state. Interface witnesses are selected during specialization and add no runtime dispatch.\n//!\n//! # Gotchas\n//! Whenever `HashKey.equals` reports two values equal, `HashKey.hash` must return the same value\n//! for both under every seed. The collection cannot detect a witness that violates this rule; such\n//! a key may become unreachable.\n//!\n//! # Examples\n//! ## Hash the fields of one key deterministically\n//! ```silk\n//! import silk.hash { Hash }\n//!\n//! import silk.u64\n//!\n//! pub fn main() -> i32 {\n//!   let seed = Hash.seed(17)\n//!   let first = Hash.mix(&seed, 4)\n//!     |> Hash.combine(9)\n//!   let second = Hash.mix(&seed, 4)\n//!     |> Hash.combine(9)\n//!   if first != second {\n//!     return 0\n//!   }\n//!   return u64.toI32(Hash.word(42).value)\n//! }\n//! ```\n\n// The hashing contract the hashed collections resolve against, and the seed every hash is computed\n// under. Ordinary Silk: no compiler phase computes a hash, recognizes this interface by spelling, or\n// treats a conformance to it as anything other than an ordinary conformance.\n//\n// The contract pairs an equivalence with a hash because a hashed collection needs both and needs\n// them to agree. The equivalence is named `equals` rather than `equivalent` for the same reason\n// `order.silk` declares `lessThan` rather than a three-way `compare`: an interface operation is\n// reachable from a generic body through the operator that spells it, and `==` spells `equals`. The\n// hash is reached by naming the bound, which is the one call shape no operator provides.\n\nimport silk.bool as bool\nimport silk.u64 as u64\n\n/// The owner of the seed, mixing, and ready-made key operations.\n///\n/// # Details\n///\n/// This struct carries no data and is never constructed by the library. Every operation is an\n/// inherent member declared in `impl Hash`, reached through `import silk.hash { Hash }`.\npub struct Hash {}\n\nimpl Hash {\n  /// Creates a deterministic hash seed from one `u64` value.\n  pub fn seed(value: u64) -> HashSeed {\n    return HashSeed { value: value }\n  }\n\n  /// Mixes the first integer field of a key with one seed into a 64-bit hash.\n  ///\n  /// # When to use\n  ///\n  /// Use this function to start a hash for an integer key or the first integer field of a key.\n  ///\n  /// # Details\n  ///\n  /// The same seed and value return the same result on all supported targets. Use [`combine`] for each\n  /// additional field that participates in equality.\n  pub fn mix(seed: &HashSeed, value: u64) -> u64 {\n    let salted = u64.wrappingAdd(value, seed.value)\n    let stepped = u64.wrappingAdd(salted, 11400714819323198485)\n    let folded = u64.bitXor(stepped, u64.shiftRight(stepped, 30))\n    let spread = u64.wrappingMultiply(folded, 13787848793156543929)\n    let refolded = u64.bitXor(spread, u64.shiftRight(spread, 27))\n    let respread = u64.wrappingMultiply(refolded, 10723151780598845931)\n    return u64.bitXor(respread, u64.shiftRight(respread, 31))\n  }\n\n  /// Continues a hash with one further value, so a key of several fields folds into one hash.\n  ///\n  /// # When to use\n  ///\n  /// Use this function after [`mix`] for each additional integer field that participates in equality.\n  pub fn combine(hashed: u64, value: u64) -> u64 {\n    let mingled = u64.bitXor(hashed, u64.wrappingAdd(value, 11400714819323198485))\n    let spread = u64.wrappingMultiply(mingled, 13787848793156543929)\n    return u64.bitXor(spread, u64.shiftRight(spread, 27))\n  }\n\n  /// Creates a [`Word`] key from one `u64` value.\n  pub fn word(value: u64) -> Word {\n    return Word { value: value }\n  }\n}\n\n/// A collection-wide value that changes deterministic hash and bucket results.\n///\n/// # Details\n///\n/// The same seed, keys, and operation sequence produce the same bucket order on all supported targets.\n/// A seed does not use allocation addresses, clocks, or ambient entropy.\npub struct HashSeed {\n  /// The seed value handed to every hash the collection computes.\n  pub value: u64\n}\n\nimpl Copy for HashSeed {}\n\n/// A compile-time equivalence and seeded-hash contract for hashed collection keys.\n///\n/// # Details\n///\n/// The `==` operator selects `equals`. A hashed collection calls `hash` with its own seed.\n///\n/// # Gotchas\n///\n/// For each seed, two equivalent keys must have equal hashes. A collection cannot check this rule.\n/// If a witness breaks the rule, a present key can become unreachable.\npub interface HashKey {\n  /// Reports whether two keys name the same collection entry.\n  ///\n  /// # Gotchas\n  ///\n  /// If this returns `true`, `HashKey.hash` must return equal hashes for both keys under each seed.\n  operator == fn equals(left: &Self, right: &Self) -> bool\n  /// Computes the key's deterministic 64-bit hash under the collection seed.\n  ///\n  /// # Gotchas\n  ///\n  /// Equivalent keys must return equal results for the same seed.\n  fn hash(value: &Self, seed: &HashSeed) -> u64\n}\n\n/// A ready-made [`HashKey`] that holds one `u64` value.\npub struct Word {\n  /// The integer this key stands for.\n  pub value: u64\n}\n\nimpl Copy for Word {}\n\nfn wordEquals(left: &Word, right: &Word) -> bool {\n  return left.value == right.value\n}\n\nfn wordHash(value: &Word, seed: &HashSeed) -> u64 {\n  return Hash.mix(seed, value.value)\n}\n\nimpl HashKey for Word { equals: Word.wordEquals hash: Word.wordHash }\n",
