    namespace: 'InsecureRandom',
    aliases: ['Xoshiro256StarStar'],
    source:
      '//! Provider-replaceable deterministic words, booleans, bounded values, and byte filling.\n//!\n//! # When to use\n//! Require [`InsecureRandom`] when a reproducible pseudorandom stream is needed. Use\n//! [`Xoshiro256StarStar`] with [`seeded`] for one stable supported-target sequence.\n//!\n//! # Details\n//! `InsecureRandom.nextU64` obtains one word from the active provider. [`nextBool`], [`below`], and [`fillBytes`]\n//! define one stable mapping from provider words to their results. Seed expansion uses SplitMix64.\n//!\n//! # Gotchas\n//! These APIs are deterministic and non-cryptographic. Do not use them for secrets, credentials,\n//! keys, nonces, tokens, or hash-flood protection.\n//!\n//! # Examples\n//! ## Reproduce the first word from one seed\n//! ```silk\n//! import silk.effect { Effect }\n//! import silk.insecure_random { InsecureRandom }\n//!\n//! pub fn main() -> i32 {\n//!   let mut provider = InsecureRandom.seeded(0)\n//!   let first = run InsecureRandom.nextU64()\n//!     |> Effect.provideMut<InsecureRandom>(&mut provider)\n//!   if first != 0x99ec5f36cb75f2b4 { return 0 }\n//!   return 42\n//! }\n//! ```\n\nimport silk.option { Option }\nimport silk.u64 as u64\nimport silk.u8 as u8\nimport silk.usize as usize\n\n/// An exclusive source of deterministic non-cryptographic `u64` words.\n///\n/// # Details\n///\n/// A provider owns its state. Each call advances only the provider supplied for the lexical Effect.\n///\n/// # Gotchas\n///\n/// This service is unsuitable for secrets, credentials, keys, nonces, tokens, and hash protection.\npub service InsecureRandom {\n  /// Returns the next deterministic word and advances the active provider once.\n  effect fn nextU64() -> u64 ? &mut InsecureRandom\n}\n\nimpl InsecureRandom {\n  /// Creates a reproducible [`Xoshiro256StarStar`] provider from one `u64` seed.\n  ///\n  /// # Details\n  ///\n  /// Every seed, including zero, expands through four successive SplitMix64 steps.\n  pub fn seeded(seed: u64) -> Xoshiro256StarStar {\n    let first = splitMix64(seed)\n    let second = splitMix64(first.state)\n    let third = splitMix64(second.state)\n    let fourth = splitMix64(third.state)\n    return Xoshiro256StarStar {\n      state0: first.value,\n      state1: second.value,\n      state2: third.value,\n      state3: fourth.value,\n    }\n  }\n\n  /// Returns whether bit 63 of the next deterministic provider word is set.\n  pub effect fn nextBool() -> bool ? &mut InsecureRandom {\n    let word = run InsecureRandom.nextU64()\n    return u64.shiftRight(word, 63) == 1\n  }\n\n  /// Returns a deterministic value below `upperExclusive`, or `None` when the bound is zero.\n  ///\n  /// # Details\n  ///\n  /// Positive bounds use complete-word rejection sampling. Progress requires eventual acceptance.\n  pub effect fn below(upperExclusive: u64) -> Option<u64> ? &mut InsecureRandom {\n    if upperExclusive == u64.MIN {\n      return Option.none<u64>()\n    }\n\n    let threshold = u64.remainder(u64.wrappingSubtract(u64.MIN, upperExclusive), upperExclusive)\n    let mut word = run InsecureRandom.nextU64()\n    while word < threshold {\n      word = run InsecureRandom.nextU64()\n    }\n    return Option.some<u64>(u64.remainder(word, upperExclusive))\n  }\n\n  /// Fills `output` from deterministic provider words in least-significant-byte-first order.\n  ///\n  /// # Details\n  ///\n  /// An empty slice consumes no word. A partial final group consumes one complete word.\n  pub effect fn fillBytes(output: &mut [u8]) -> () ? &mut InsecureRandom {\n    let mut index = usize.ZERO\n    while index < output.length {\n      let mut word = run InsecureRandom.nextU64()\n      let mut byteIndex = u64.MIN\n      while byteIndex < 8 {\n        if index == output.length {\n          return ()\n        }\n        output[index] = u64.toU8(u64.bitAnd(word, 255))\n        word = u64.shiftRight(word, 8)\n        index = index + usize.ONE\n        byteIndex = byteIndex + 1\n      }\n    }\n    return ()\n  }\n}\n\n/// A deterministic xoshiro256** provider with four private `u64` state words.\n///\n/// # Details\n///\n/// The sequence is stable on every Silk engine and is not cryptographically secure.\npub struct Xoshiro256StarStar {\n  state0: u64\n  state1: u64\n  state2: u64\n  state3: u64\n}\n\nstruct SplitMix64Step {\n  state: u64\n  value: u64\n}\n\nfn splitMix64(state: u64) -> SplitMix64Step {\n  let next = u64.wrappingAdd(state, 0x9e3779b97f4a7c15)\n  let first = u64.bitXor(next, u64.shiftRight(next, 30))\n  let spread = u64.wrappingMultiply(first, 0xbf58476d1ce4e5b9)\n  let second = u64.bitXor(spread, u64.shiftRight(spread, 27))\n  let respread = u64.wrappingMultiply(second, 0x94d049bb133111eb)\n  return SplitMix64Step {\n    state: next,\n    value: u64.bitXor(respread, u64.shiftRight(respread, 31)),\n  }\n}\n\neffect fn xoshiroNext(self: &mut Xoshiro256StarStar) -> u64 {\n  let multiplied = u64.wrappingMultiply(self.state1, 5)\n  let result = u64.wrappingMultiply(u64.rotateLeft(multiplied, 7), 9)\n  let shifted = u64.shiftLeft(self.state1, 17)\n\n  self.state2 = u64.bitXor(self.state2, self.state0)\n  self.state3 = u64.bitXor(self.state3, self.state1)\n  self.state1 = u64.bitXor(self.state1, self.state2)\n  self.state0 = u64.bitXor(self.state0, self.state3)\n  self.state2 = u64.bitXor(self.state2, shifted)\n  self.state3 = u64.rotateLeft(self.state3, 45)\n\n  return result\n}\n\nimpl InsecureRandom for Xoshiro256StarStar {\n  nextU64: Xoshiro256StarStar.xoshiroNext\n}\n',
