    namespace: 'StdoutLogger',
    source:
      '//! Native logging through the process standard-output descriptor.\n//!\n//! # When to use\n//! Provide [`StdoutLogger`] at a native application edge. Portable code uses `silk.logger.Logger`\n//! and can replace this provider with `silk.logger.InMemoryLogger`.\n//!\n//! # Details\n//! Construction performs no output. Each log writes exactly the message\'s UTF-8 bytes without\n//! adding a newline or severity label. Descriptor failures become LogError code 3.\n//!\n//! # Gotchas\n//! The descriptor remains process-owned. A failed write may have committed a prefix.\n//! The module is empty on WebAssembly and no-libc profiles.\n\nstatic if (Intrinsic.targetOperatingSystem() == "darwin" && Intrinsic.targetArchitecture() == "aarch64" && Intrinsic.targetAbi() == "apple" && Intrinsic.profileText("libc") == "system") || (Intrinsic.targetOperatingSystem() == "linux" && Intrinsic.targetAbi() == "gnu" && Intrinsic.profileText("libc") == "gnu" && (Intrinsic.targetArchitecture() == "aarch64" || Intrinsic.targetArchitecture() == "x86_64")) {\n  import silk.writer { WriterError, Writer }\n  import silk.os_writer { StdoutWriter }\n  import silk.logger { Logger, LogError, LogLevel }\n  import silk.effect { Effect }\n  import silk.result { Result }\n  import silk.string { String }\n\n/// A [`Logger`] provider that writes each complete message to process standard output.\n///\n/// # Details\n///\n/// The provider ignores the severity for physical formatting and writes only the UTF-8 message\n/// bytes. It adds no newline and performs no message allocation.\npub struct StdoutLogger {}\n\nimpl StdoutLogger {\n  /// Creates a native stdout logger without writing or acquiring a descriptor.\n  pub fn make() -> StdoutLogger { return StdoutLogger {} }\n\n  effect fn writeStdout(\n    self: &mut Self,\n    level: LogLevel,\n    message: string\n  ) -> () ! LogError {\n    let mut streams = StdoutWriter.make()\n    let bytes = String.utf8Bytes(message)\n    let completed = run Effect.result(writeStdoutBytes(&mut streams, bytes))\n    return match move completed {\n      Result<(), WriterError>.Success { value: _ } => ()\n      Result<(), WriterError>.Failure { error: _ } => run writeFailure()\n    }\n  }\n}\n\neffect fn writeStdoutBytes(\n  writer: &mut StdoutWriter,\n  message: &[u8]\n) -> () ! WriterError {\n  run Intrinsic.bindRequirementMut(Writer.writeAll(message), writer)\n}\n\neffect fn writeFailure() -> never ! LogError { fail Logger.failure(3) }\n\nimpl Logger for StdoutLogger {\n  log: StdoutLogger.writeStdout\n}\n\n}\n\n',
