    source:
      '//! Source-owned byte clearing for the Darwin LLVM zero-fill helper.\n\nimport silk.pointer { Pointer }\n\n/// Writes zero to each of the `count` destination bytes.\n///\n/// # Gotchas\n///\n/// The caller must provide a live writable range of `count` bytes.\nexport "C" fn bzero(destination: ?[*]mut u8, count: usize) -> () {\n  if count == 0 { return () }\n  unsafe {\n    let output = Intrinsic.pointerRequalify<?[*]mut u8, [*]mut u8>(destination)\n    let mut index: usize = 0\n    while index < count {\n      Pointer.write<u8>(Pointer.atMut<u8>(output, index), 0)\n      index = index + 1\n    }\n  }\n  return ()\n}\n',
