      '//! Byte-wise compiler support with explicit C linkage and no runtime services.\n\nimport silk.pointer { Pointer }\nimport silk.i32 as i32\n\n/// Copies `count` bytes and returns the original destination address.\n///\n/// # Gotchas\n///\n/// The caller must provide live readable source bytes and writable destination bytes.\n/// The ranges can overlap; each output byte receives its original source value.\nexport "C" fn memmove(destination: ?[*]mut u8, source: ?[*]const u8, count: usize) -> ?[*]mut u8 {\n  if count == 0 { return destination }\n  unsafe {\n    let output = Intrinsic.pointerRequalify<?[*]mut u8, [*]mut u8>(destination)\n    let input = Intrinsic.pointerRequalify<?[*]const u8, [*]const u8>(source)\n    if Pointer.addressMany<u8>(destination) > Pointer.addressMany<u8>(source) {\n      let mut index = count\n      while index > 0 {\n        index = index - 1\n      let value = Pointer.read<u8>(Pointer.at<u8>(input, index))\n      Pointer.write<u8>(Pointer.atMut<u8>(output, index), value)\n      }\n      return destination\n    }\n    let mut index: usize = 0\n    while index < count {\n      let value = Pointer.read<u8>(Pointer.at<u8>(input, index))\n      Pointer.write<u8>(Pointer.atMut<u8>(output, index), value)\n      index = index + 1\n    }\n    return destination\n  }\n}\n',
