    source:
      '//! Byte-wise compiler support with explicit C linkage and no runtime services.\n\nimport silk.pointer { Pointer }\nimport silk.i32 as i32\n\n/// Writes the low eight bits of `value` to `count` bytes and returns the destination.\n///\n/// # Gotchas\n///\n/// The caller must provide a live writable destination range of `count` bytes.\nexport "C" fn memset(destination: ?[*]mut u8, value: i32, count: usize) -> ?[*]mut u8 {\n  if count == 0 { return destination }\n  unsafe {\n    let output = Intrinsic.pointerRequalify<?[*]mut u8, [*]mut u8>(destination)\n    let byte = i32.toU8(value & 255)\n    let mut index: usize = 0\n    while index < count {\n      Pointer.write<u8>(Pointer.atMut<u8>(output, index), byte)\n      index = index + 1\n    }\n    return destination\n  }\n}\n',
